/bin/zsh -lc "cat > tb.sv <<'EOF'
module tb;
  reg clk = 0;
  reg rst = 0;
  reg data = 0;
  wire flag;
  TopModule dut(.clk(clk), .rst(rst), .data(data), .flag(flag));
  always #5 clk = ~clk;

  task drive(input bit d);
    begin
      data = d;
      @(posedge clk);
      #1;
      "'$display("t=%0t data=%0b state=%0d flag=%0b", $time, d, dut.state, flag);
    end
  endtask

  initial begin
    repeat (1) @(posedge clk);
    rst = 1;
    drive(1);
    drive(0);
    drive(1);
    drive(0);
    drive(1);
    drive(1);
    drive(0);
    $finish;
  end
endmodule
EOF
iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

